<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> System</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Security</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Cryptography</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">X509Certificates</span><span style="color:#ABB2BF;">;</span></span>
